    public sealed partial class GameRoot
    {
        Mission MakeContinuationMission(int role,int chapter,int choice)
        {
            int part=chapter-9;
            if(role==13)
            {
                var prison=PrisonMission(chapter==StoryBook.ChapterCount-1 && choice==1?0:1);prison.Release=chapter==StoryBook.ChapterCount-1 && choice==0;return prison;
            }
            if(role==12)
                return new Mission("Караульная проверка","Проверь журнал, пост и передачу смены.",900+part*140,false,new[]{new Vector3(930,1,-385),new Vector3(1130,1,-395),WorldBuilder.Places[12].Position},"Проверь ведомость на посту","Сверь периметр и передачу ключей","Доложи Хейзу о результате");
            Vector3 home=WorldBuilder.Places[role].Position;
            Vector3 district=StateBuilder.ExpansionCenters[(part+role+choice)%StateBuilder.ExpansionCenters.Length]+new Vector3(6,0,35+part*12);
            Vector3 next=(part+choice)%2==0?StateBuilder.SanFierro:StateBuilder.LasVenturas;next+=new Vector3(6,0,40+part*9);
            string first=role==4?"Окажи помощь пациенту":role==5?"Потуши очаг пожара":role==8?"Забери ремонтное оборудование":role==6?"Забери пассажира":role==7?"Проверь груз и загрузи партию":"Проверь адрес новой зацепки";
            var mission=new Mission("Продолжение","Расширенная сюжетная операция",1200+part*175,true,new[]{role==8?home:district,role==8?district:next,home},first,role==8?"Выполни ремонт на месте":"Выполни передачу и получи подтверждение","Вернись к своему контакту с результатом");
            bool armed=role==1||role==2||role==3||role==9||role==14;
            mission.Combat=armed && (part==2||part==5||part==8||part==10);
            mission.Fleeing=(role==9||role==14) && (part==3||part==7||part==10);
            if(part==7)mission.TimeLimit=1000;
            return mission;
        }
    }
